def _ensure_bench_input(path: Path, fallback: Path):
    """B1b: prefer the input under the (configurable) results root; if absent
    and a canonical copy exists in the repo, copy it; else build it."""
    if path.exists():
        return torch.load(path, map_location="cpu", weights_only=False)
    if fallback.exists():
        path.parent.mkdir(parents=True, exist_ok=True)
        import shutil
        shutil.copyfile(str(fallback), str(path))
        return torch.load(path, map_location="cpu", weights_only=False)
    return None


def _ensure_fmnist_bench_input() -> torch.Tensor:
    """First 256 TEST images, inputs only (no labels). Saved once."""
    got = _ensure_bench_input(FMNIST_BENCH_INPUT, _CANONICAL_BENCH_DIR / "fmnist_bench_input.pt")
    if got is not None:
        return got
    _, _, _, _, te_x, _, _, _ = fmnist_split_tensors()
    BENCH_DIR.mkdir(parents=True, exist_ok=True)
    torch.save(te_x[:256].contiguous(), FMNIST_BENCH_INPUT)
    return torch.load(FMNIST_BENCH_INPUT, map_location="cpu", weights_only=True)

