import warnings; warnings.filterwarnings('ignore')
import torch as T
import torch.nn.functional as F
from lab3.compact import CompactModel
from lab3.models import build_model
from lab3.evaln import load_checkpoint
import copy

for arch in ('mlp','cnn','gcn'):
    parent,_ = load_checkpoint(arch,0)
    sd = {k:v.detach().clone() for k,v in parent.state_dict().items()}
    cm = CompactModel(arch, sd, 'csr').eval()
    parent.eval()
    g = T.Generator().manual_seed(7)
    if arch=='gcn':
        x = T.randn(30,1433,generator=g); ei = T.randint(0,30,(2,120),generator=g)
        p = copy.deepcopy(parent); cm2 = copy.deepcopy(cm)
        for m in p.modules():
            for a in list(vars(m)):
                if a.startswith('_cached'): setattr(m,a,None)
        a = p(x,ei); b = cm2(x,ei)
    else:
        x = T.randn(2,1,28,28,generator=g)
        a = parent(x); b = cm(x)
    print(arch, 'match:', T.allclose(a,b,atol=1e-5), (a-b).abs().max().item())
EOF

